css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-qs{width:min(820px,100%);display:grid;gap:1.6em;text-align:center;justify-items:center}
.fx-qs .eye{font-size:.78em;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--accent)}
.fx-qs .stack{display:grid;width:100%}
.fx-qs .sl{grid-area:1/1;margin:0;display:grid;gap:1.6em;justify-items:center;align-content:center;opacity:0;visibility:hidden;transform:translateY(14px);transition:opacity calc(.6s/var(--speed)) ease,transform calc(.6s/var(--speed)) ease,visibility 0s calc(.6s/var(--speed))}
.fx-qs .sl.on{opacity:1;visibility:visible;transform:none;transition-delay:0s}
.fx-qs blockquote{margin:0;font:500 clamp(1.4em,3.6vw,2.2em)/1.35 var(--font-heading);letter-spacing:-.01em;max-width:28ch}
.fx-qs figcaption{display:flex;align-items:center;gap:.9em;text-align:left}
.fx-qs .av{width:3em;height:3em;border-radius:50%;display:grid;place-items:center;font:700 .85em var(--font-body);color:var(--on-primary);flex:none}
.fx-qs .av::before,.fx-qs .av::after{display:none}
.fx-qs figcaption b{display:block}.fx-qs figcaption small{opacity:.62;font-size:.88em}
.fx-qs .ctl{display:flex;align-items:center;gap:1.2em}
.fx-qs .ctl>button{width:2.7em;height:2.7em;border-radius:50%;border:1.5px solid var(--primary);background:transparent;color:var(--primary);font-size:1em;cursor:pointer;transition:background .25s,color .25s}
.fx-qs .ctl>button:hover{background:var(--primary);color:var(--on-primary)}
.fx-qs .dots{display:flex;gap:.3em}.fx-qs .dots button{all:unset;box-sizing:border-box;padding:.5em;cursor:pointer}
.fx-qs .dots button::before{content:"";display:block;width:.55em;height:.55em;border-radius:99px;background:color-mix(in srgb,var(--text) 22%,transparent);transition:width .3s,background .3s}
.fx-qs .dots button[aria-current=true]::before{width:1.8em;background:var(--accent)}
.fx-qs button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
@media(prefers-reduced-motion:reduce){.fx-qs .sl{transition:none;transform:none}}
/* touch: :hover mirrored as .is-tap */
.fx-qs .ctl>button.is-tap{background:var(--primary);color:var(--on-primary)}

