(function(){document.querySelectorAll('.fx-qs').forEach(function(r){var sl=[].slice.call(r.querySelectorAll('.sl')),dots=r.querySelector('.dots'),i=0,t,hold=false;
var rm=matchMedia('(prefers-reduced-motion:reduce)').matches;
sl.forEach(function(s,k){var b=document.createElement('button');b.setAttribute('aria-label','Show quote '+(k+1));b.addEventListener('click',function(){go(k)});dots.appendChild(b)});
var ds=dots.children;
function go(n){i=(n+sl.length)%sl.length;sl.forEach(function(s,k){s.classList.toggle('on',k===i);s.setAttribute('aria-hidden',k!==i)});for(var k=0;k<ds.length;k++)ds[k].setAttribute('aria-current',k===i)}
var bs=r.querySelectorAll('.ctl>button');bs[0].addEventListener('click',function(){go(i-1)});bs[1].addEventListener('click',function(){go(i+1)});
r.addEventListener('mouseenter',function(){hold=true});r.addEventListener('mouseleave',function(){hold=false});r.addEventListener('focusin',function(){hold=true});r.addEventListener('focusout',function(){hold=false});
function sp(){return parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--speed'))||1}
if(!rm)(function loop(){t=setTimeout(function(){if(!hold)go(i+1);loop()},6500/sp())})();
go(0)})})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
